    '&НаСервере',
    'Процедура УстановитьАвтоЗачетАвансовДокумента(ДокОбъект)',
    '\tЕсли ДокОбъект = Неопределено Тогда',
    '\t\tВозврат;',
    '\tКонецЕсли;',
    '\tПопытка',
    '\t\tУстановитьЕслиЕсть(ДокОбъект, "СпособЗачетаАвансов", Перечисления.СпособыЗачетаАвансов.Автоматически);',
    '\tИсключение',
