    '\tИсключение',
    '\tКонецПопытки;',
    'КонецПроцедуры',
    '',
    '&НаСервере',
    'Функция ПолучитьИзСоответствия(Карта, Ключ, ПоУмолчанию = Неопределено)',
    '\tЕсли Карта = Неопределено Тогда',
    '\t\tВозврат ПоУмолчанию;',
    '\tКонецЕсли;',
