    'Функция ПолучитьСтавкуНДСРасчетную(ЧисловаяСтавка)',
    '\tЕсли ЧисловаяСтавка = 10 Тогда',
    '\t\tПопытка',
    '\t\t\tВозврат Перечисления.СтавкиНДС.НДС10_110;',
    '\t\tИсключение',
