    '\t\t\tЗапросВсеКПрост = Новый Запрос;',
    '\t\t\tЗапросВсеКПрост.Текст = "ВЫБРАТЬ ПЕРВЫЕ 5000 К.Ссылка КАК Ссылка, К.ИНН КАК ИНН, К.Наименование КАК Наименование, К.Наименование КАК НаименованиеПолное ИЗ Справочник.Контрагенты КАК К ГДЕ НЕ К.ПометкаУдаления И НЕ К.ЭтоГруппа";',
    '\t\t\tТабКонтрБазы = ЗапросВсеКПрост.Выполнить().Выгрузить();',
    '\t\tИсключение',
    '\t\t\tТабКонтрБазы = Неопределено;',
    '\t\tКонецПопытки;',
    '\tКонецПопытки;',
    '\tЕсли ТабКонтрБазы = Неопределено Тогда',
    '\t\tВозврат;',
    '\tКонецЕсли;',
    '\tСчетчикИтераций = 0;',
    '\tДля Каждого СтрК Из ТабКонтрБазы Цикл',
    '\t\tСчетчикИтераций = СчетчикИтераций + 1;',
    '\t\tЕсли СчетчикИтераций > 5000 Тогда',
