    '\t\t\tКэшКонтрПоНормИмени.Вставить("EXACT|" + ИмяТочн, СтрК.Ссылка);',
    '\t\tКонецЕсли;',
    '\t\tПолнТочн = НРег(СокрЛП(Строка(СтрК.НаименованиеПолное)));',
    '\t\tЕсли НЕ ПустаяСтрока(ПолнТочн) И ПолучитьИзСоответствия(КэшКонтрПоНормИмени, "EXACT|" + ПолнТочн, Неопределено) = Неопределено Тогда',
    '\t\t\tКэшКонтрПоНормИмени.Вставить("EXACT|" + ПолнТочн, СтрК.Ссылка);',
