    '\t\tНорм1 = НормализоватьИмяКонтрагентаДляПоиска(СтрК.Наименование);',
    '\t\tЕсли СтрДлина(Норм1) >= 2 И ПолучитьИзСоответствия(КэшКонтрПоНормИмени, Норм1, Неопределено) = Неопределено Тогда',
    '\t\t\tКэшКонтрПоНормИмени.Вставить(Норм1, СтрК.Ссылка);',
    '\t\tКонецЕсли;',
    '\t\tНорм2 = НормализоватьИмяКонтрагентаДляПоиска(СтрК.НаименованиеПолное);',
