    '',
    '&НаСервере',
    'Процедура ЗагрузитьКэшДоговоровБазы1С(КэшДоговоров)',
    '\tПопытка',
    '\t\tЗапросВсеД = Новый Запрос;',
    '\t\tЗапросВсеД.Текст = "ВЫБРАТЬ ПЕРВЫЕ 5000 Д.Ссылка КАК Ссылка, Д.Владелец КАК Владелец, Д.Наименование КАК Наименование, Д.Номер КАК Номер, Д.ВидДоговора КАК ВидДоговора ИЗ Справочник.ДоговорыКонтрагентов КАК Д ГДЕ НЕ Д.ПометкаУдаления И НЕ Д.ЭтоГруппа УПОРЯДОЧИТЬ ПО Д.Код";',
