    '\t\tДля Каждого СтрД Из ТабДогБазы Цикл',
    '\t\t\tСчетчикИтераций = СчетчикИтераций + 1;',
    '\t\t\tЕсли СчетчикИтераций > 5000 Тогда',
    '\t\t\t\tПрервать;',
    '\t\t\tКонецЕсли;',
    '\t\t\tКлючВлад = КлючСсылкиДляКэша(СтрД.Владелец);',
