    '\t\t\tКодВида = КодВидаДоговораДляКэша(СтрД.ВидДоговора);',
    '\t\t\tБазКлюч = КлючВлад + "|" + КодВида;',
    '\t\t\tЕсли ПолучитьИзСоответствия(КэшДоговоров, БазКлюч, Неопределено) = Неопределено Тогда',
    '\t\t\t\tКэшДоговоров.Вставить(БазКлюч, СтрД.Ссылка);',
    '\t\t\tКонецЕсли;',
    '\t\t\tИмяДНРег = НРег(СокрЛП(Строка(СтрД.Наименование)));',
    '\t\t\tЕсли НЕ ПустаяСтрока(ИмяДНРег) Тогда',
    '\t\t\t\tКэшДоговоров.Вставить("NAME|" + БазКлюч + "|" + ИмяДНРег, СтрД.Ссылка);',
    '\t\t\tКонецЕсли;',
    '\t\t\tНомДНРег = НРег(СокрЛП(Строка(СтрД.Номер)));',
    '\t\t\tЕсли НЕ ПустаяСтрока(НомДНРег) Тогда',
    '\t\t\t\tКэшДоговоров.Вставить("NUM|" + БазКлюч + "|" + НомДНРег, СтрД.Ссылка);',
    '\t\t\tКонецЕсли;',
    '\t\tКонецЦикла;',
    '\tИсключение',
    '\tКонецПопытки;',
    'КонецПроцедуры',
    '',
    '&НаСервере',
    'Функция НайтиИлиСоздатьКонтрагента(ДанныеКонтр, КэшКонтрПоИНН = Неопределено, КэшКонтрПоНормИмени = Неопределено)',
    '\tИмяК = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеКонтр, "name", "")));',
    '\tПолноеИмяК = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеКонтр, "fullName", ИмяК)));',
    '\tИННК = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеКонтр, "inn", "")));',
