    '\tВидК = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеКонтр, "kind", "ЮридическоеЛицо")));',
    '',
    '\tЕсли ПустаяСтрока(ИмяК) Тогда',
    '\t\tВозврат Справочники.Контрагенты.ПустаяСсылка();',
    '\tКонецЕсли;',
    '',
