    '\tЭталонНормК = НормализоватьИмяКонтрагентаДляПоиска(ИмяК);',
    '\tЭталонПолнНормК = НормализоватьИмяКонтрагентаДляПоиска(ПолноеИмяК);',
    '\tЕсли КэшКонтрПоНормИмени <> Неопределено Тогда',
    '\t\tИзКэшаТочн1 = ПолучитьИзСоответствия(КэшКонтрПоНормИмени, "EXACT|" + НРег(ИмяК), Неопределено);',
    '\t\tЕсли ЗначениеЗаполнено(ИзКэшаТочн1) Тогда',
