    '\t\t\tЕсли ЗначениеЗаполнено(ИзКэшаТочн2) Тогда',
    '\t\t\t\tВозврат ИзКэшаТочн2;',
    '\t\t\tКонецЕсли;',
    '\t\tКонецЕсли;',
    '\t\tЕсли СтрДлина(ЭталонНормК) >= 2 Тогда',
    '\t\t\tИзКэшаНорм1 = ПолучитьИзСоответствия(КэшКонтрПоНормИмени, ЭталонНормК, Неопределено);',
    '\t\t\tЕсли ЗначениеЗаполнено(ИзКэшаНорм1) Тогда',
    '\t\t\t\tВозврат ИзКэшаНорм1;',
    '\t\t\tКонецЕсли;',
    '\t\tКонецЕсли;',
    '\t\tЕсли СтрДлина(ЭталонПолнНормК) >= 2 Тогда',
    '\t\t\tИзКэшаНорм2 = ПолучитьИзСоответствия(КэшКонтрПоНормИмени, ЭталонПолнНормК, Неопределено);',
    '\t\t\tЕсли ЗначениеЗаполнено(ИзКэшаНорм2) Тогда',
    '\t\t\t\tВозврат ИзКэшаНорм2;',
    '\t\t\tКонецЕсли;',
    '\t\tКонецЕсли;',
    '\tИначе',
    '\t\tЕсли НЕ ПустаяСтрока(ИННК) Тогда',
    '\t\t\tПопытка',
    '\t\t\t\tЗапросК = Новый Запрос;',
    '\t\t\t\tЗапросК.Текст = "ВЫБРАТЬ ПЕРВЫЕ 1 К.Ссылка КАК Ссылка ИЗ Справочник.Контрагенты КАК К ГДЕ НЕ К.ПометкаУдаления И НЕ К.ЭтоГруппа И К.ИНН = &ИНН";',
    '\t\t\t\tЗапросК.УстановитьПараметр("ИНН", ИННК);',
