    '\t\t\t\tЕсли ТабК.Количество() > 0 Тогда',
    '\t\t\t\t\tВозврат ТабК[0].Ссылка;',
    '\t\t\t\tКонецЕсли;',
    '\t\t\tИсключение',
    '\t\t\tКонецПопытки;',
    '\t\tКонецЕсли;',
    '\t\tНайденПоИмени = Справочники.Контрагенты.НайтиПоНаименованию(ИмяК);',
