    'Функция НайтиИлиСоздатьДоговор(КонтрагентСсылка, ОрганизацияСсылка, ДанныеДог, КэшДоговоров = Неопределено, ВалютаРубПереданная = Неопределено)',
    '\tЕсли НЕ ЗначениеЗаполнено(КонтрагентСсылка) Тогда',
