    '\tИмяДог = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеДог, "name", "Основной договор")));',
    '\tНомерДог = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеДог, "number", "")));',
    '\tДатаДогСтр = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеДог, "date", "")));',
