    '\t\tВидДогПереч = Перечисления.ВидыДоговоровКонтрагентов.СПокупателем;',
    '\tИначеЕсли ВидДогСтр = "Прочее" Тогда',
    '\t\tВидДогПереч = Перечисления.ВидыДоговоровКонтрагентов.Прочее;',
