    '\t\tУстановитьЕслиЕсть(НовоеПодр, "Владелец", ОрганизацияСсылка);',
    '\t\tНовоеПодр.Наименование = ИмяПодразделения;',
    '\t\tНовоеПодр.Записать();',
    '\t\tВозврат НовоеПодр.Ссылка;',
