    '&НаСервере',
    'Функция НайтиИлиСоздатьФизЛицоИСотрудника(ОрганизацияСсылка, ДанныеСотр)',
    '\tРезультат = Новый Структура("ФизЛицо, Сотрудник", Неопределено, Неопределено);',
    '\tФИО = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеСотр, "fullName", "")));',
    '\tЕсли ПустаяСтрока(ФИО) Тогда',
