    '\tКонецЕсли;',
    '',
    '\tФизЛицоСсылка = Справочники.ФизическиеЛица.НайтиПоНаименованию(ФИО);',
    '\tЕсли НЕ ЗначениеЗаполнено(ФизЛицоСсылка) Тогда',
    '\t\tНовоеФЛ = Справочники.ФизическиеЛица.СоздатьЭлемент();',
    '\t\tНовоеФЛ.Наименование = ФИО;',
    '\t\tУстановитьЕслиЕсть(НовоеФЛ, "ФИО", ФИО);',
    '\t\tНовоеФЛ.Записать();',
    '\t\tФизЛицоСсылка = НовоеФЛ.Ссылка;',
    '\tКонецЕсли;',
    '',
    '\tСотрудникСсылка = Справочники.Сотрудники.НайтиПоНаименованию(ФИО);',
    '\tЕсли НЕ ЗначениеЗаполнено(СотрудникСсылка) Тогда',
    '\t\tНовыйСотр = Справочники.Сотрудники.СоздатьЭлемент();',
    '\t\tНовыйСотр.Наименование = ФИО;',
    '\t\tУстановитьЕслиЕсть(НовыйСотр, "ГоловнаяОрганизация", ОрганизацияСсылка);',
    '\t\tУстановитьЕслиЕсть(НовыйСотр, "ФизическоеЛицо", ФизЛицоСсылка);',
    '\t\tНовыйСотр.Записать();',
    '\t\tСотрудникСсылка = НовыйСотр.Ссылка;',
    '\tКонецЕсли;',
    '',
    '\tРезультат.ФизЛицо = ФизЛицоСсылка;',
    '\tРезультат.Сотрудник = СотрудникСсылка;',
    '\tВозврат Результат;',
    'КонецФункции',
    '',
    '&НаСервере',
    'Функция НайтиИлиСоздатьОС(ДанныеОС)',
