    '&НаСервере',
    'Функция НайтиИлиСоздатьНоменклатурнуюГруппу(ИмяГруппы)',
    '\tЧистГруппа = ?(ПустаяСтрока(СокрЛП(ИмяГруппы)), "Основная номенклатурная группа", СокрЛП(ИмяГруппы));',
    '\tНайденНГ = Справочники.НоменклатурныеГруппы.НайтиПоНаименованию(ЧистГруппа);',
    '\tЕсли ЗначениеЗаполнено(НайденНГ) Тогда',
    '\t\tВозврат НайденНГ;',
    '\tКонецЕсли;',
    '\tНоваяНГ = Справочники.НоменклатурныеГруппы.СоздатьЭлемент();',
    '\tНоваяНГ.Наименование = ЧистГруппа;',
