    '\t\t\t\tМассивСкладов.Добавить(Зап);',
    '\t\t\tКонецЦикла;',
    '\t\tИсключение',
    '\t\tКонецПопытки;',
    '\t\tВсеСправочники.Вставить("Склады", МассивСкладов);',
    '',
    '\t\tМассивПодр = Новый Массив;',
    '\t\tПопытка',
    '\t\t\tЗапрПодр = Новый Запрос("ВЫБРАТЬ Спр.Код КАК Код, Спр.Наименование КАК Наименование ИЗ Справочник.ПодразделенияОрганизаций КАК Спр ГДЕ НЕ Спр.ПометкаУдаления И НЕ Спр.ЭтоГруппа");',
    '\t\t\tДля Каждого СтрПодр Из ЗапрПодр.Выполнить().Выгрузить() Цикл',
    '\t\t\t\tЗап = Новый Соответствие;',
    '\t\t\t\tЗап.Вставить("Код", Строка(СтрПодр.Код));',
    '\t\t\t\tЗап.Вставить("Наименование", Строка(СтрПодр.Наименование));',
    '\t\t\t\tМассивПодр.Добавить(Зап);',
    '\t\t\tКонецЦикла;',
    '\t\tИсключение',
    '\t\tКонецПопытки;',
    '\t\tВсеСправочники.Вставить("Подразделения", МассивПодр);',
    '',
    '\t\tМассивКонтр = Новый Массив;',
    '\t\tПопытка',
    '\t\t\tЗапрКонтр = Новый Запрос("ВЫБРАТЬ Спр.Код КАК Код, Спр.Наименование КАК Наименование, Спр.ИНН КАК ИНН, Спр.КПП КАК КПП ИЗ Справочник.Контрагенты КАК Спр ГДЕ НЕ Спр.ПометкаУдаления И НЕ Спр.ЭтоГруппа");',
    '\t\t\tДля Каждого СтрКонтр Из ЗапрКонтр.Выполнить().Выгрузить() Цикл',
