    '\t\t\t\tЗап.Вставить("ИНН", Строка(СтрКонтр.ИНН));',
    '\t\t\t\tЗап.Вставить("КПП", Строка(СтрКонтр.КПП));',
    '\t\t\t\tМассивКонтр.Добавить(Зап);',
    '\t\t\tКонецЦикла;',
    '\t\tИсключение',
    '\t\tКонецПопытки;',
    '\t\tВсеСправочники.Вставить("Контрагенты", МассивКонтр);',
    '',
    '\t\tМассивДог = Новый Массив;',
    '\t\tПопытка',
    '\t\t\tЗапрДог = Новый Запрос("ВЫБРАТЬ Спр.Код КАК Код, Спр.Наименование КАК Наименование, ПРЕДСТАВЛЕНИЕ(Спр.Владелец) КАК Владелец, ПРЕДСТАВЛЕНИЕ(Спр.ВидДоговора) КАК ВидДоговора ИЗ Справочник.ДоговорыКонтрагентов КАК Спр ГДЕ НЕ Спр.ПометкаУдаления И НЕ Спр.ЭтоГруппа");',
    '\t\t\tДля Каждого СтрДог Из ЗапрДог.Выполнить().Выгрузить() Цикл',
    '\t\t\t\tЗап = Новый Соответствие;',
    '\t\t\t\tЗап.Вставить("Код", Строка(СтрДог.Код));',
