    '\t\t\t\tЗап.Вставить("Владелец", Строка(СтрДог.Владелец));',
    '\t\t\t\tЗап.Вставить("ВидДоговора", Строка(СтрДог.ВидДоговора));',
    '\t\t\t\tМассивДог.Добавить(Зап);',
    '\t\t\tКонецЦикла;',
    '\t\tИсключение',
    '\t\tКонецПопытки;',
    '\t\tВсеСправочники.Вставить("ДоговорыКонтрагентов", МассивДог);',
    '',
    '\t\tМассивНом = Новый Массив;',
    '\t\tПопытка',
    '\t\t\tЗапрНом = Новый Запрос("ВЫБРАТЬ Спр.Код КАК Код, Спр.Наименование КАК Наименование, Спр.Услуга КАК Услуга ИЗ Справочник.Номенклатура КАК Спр ГДЕ НЕ Спр.ПометкаУдаления И НЕ Спр.ЭтоГруппа");',
    '\t\t\tДля Каждого СтрНом Из ЗапрНом.Выполнить().Выгрузить() Цикл',
