    '\t\t\t\tЗап.Вставить("Наименование", Строка(СтрНГ.Наименование));',
    '\t\t\t\tМассивНГ.Добавить(Зап);',
    '\t\t\tКонецЦикла;',
    '\t\tИсключение',
    '\t\tКонецПопытки;',
    '\t\tВсеСправочники.Вставить("НоменклатурныеГруппы", МассивНГ);',
    '',
    '\t\tМассивСотр = Новый Массив;',
    '\t\tПопытка',
    '\t\t\tЗапрСотр = Новый Запрос("ВЫБРАТЬ Спр.Код КАК Код, Спр.Наименование КАК Наименование ИЗ Справочник.Сотрудники КАК Спр ГДЕ НЕ Спр.ПометкаУдаления И НЕ Спр.ЭтоГруппа");',
    '\t\t\tДля Каждого СтрСотр Из ЗапрСотр.Выполнить().Выгрузить() Цикл',
    '\t\t\t\tЗап = Новый Соответствие;',
    '\t\t\t\tЗап.Вставить("Код", Строка(СтрСотр.Код));',
    '\t\t\t\tЗап.Вставить("Наименование", Строка(СтрСотр.Наименование));',
    '\t\t\t\tМассивСотр.Добавить(Зап);',
