    '\t\tИсключение',
    '\t\tКонецПопытки;',
    '\t\tВсеСправочники.Вставить("Сотрудники", МассивСотр);',
    '',
    '\t\tМассивОС = Новый Массив;',
    '\t\tПопытка',
    '\t\t\tЗапрОС = Новый Запрос("ВЫБРАТЬ Спр.Код КАК Код, Спр.Наименование КАК Наименование ИЗ Справочник.ОсновныеСредства КАК Спр ГДЕ НЕ Спр.ПометкаУдаления И НЕ Спр.ЭтоГруппа");',
    '\t\t\tДля Каждого СтрОСБ0 Из ЗапрОС.Выполнить().Выгрузить() Цикл',
