    '',
    '\t\tМассивРБП = Новый Массив;',
    '\t\tПопытка',
    '\t\t\tЗапрРБП = Новый Запрос("ВЫБРАТЬ Спр.Код КАК Код, Спр.Наименование КАК Наименование, Спр.Сумма КАК Сумма, Спр.ДатаНачалаСписания КАК ДатаНачалаСписания, Спр.ДатаОкончанияСписания КАК ДатаОкончанияСписания ИЗ Справочник.РасходыБудущихПериодов КАК Спр ГДЕ НЕ Спр.ПометкаУдаления И НЕ Спр.ЭтоГруппа");',
    '\t\t\tДля Каждого СтрРБПБ0 Из ЗапрРБП.Выполнить().Выгрузить() Цикл',
    '\t\t\t\tЗап = Новый Соответствие;',
    '\t\t\t\tЗап.Вставить("Код", Строка(СтрРБПБ0.Код));',
