    '\t\t\t\t\tЗап.Вставить("ДатаНачалаСписания", Формат(СтрРБПБ0.ДатаНачалаСписания, "ДФ=гггг-ММ-дд"));',
    '\t\t\t\tКонецЕсли;',
    '\t\t\t\tЕсли ЗначениеЗаполнено(СтрРБПБ0.ДатаОкончанияСписания) Тогда',
    '\t\t\t\t\tЗап.Вставить("ДатаОкончанияСписания", Формат(СтрРБПБ0.ДатаОкончанияСписания, "ДФ=гггг-ММ-дд"));',
    '\t\t\t\tКонецЕсли;',
    '\t\t\t\tМассивРБП.Добавить(Зап);',
    '\t\t\tКонецЦикла;',
    '\t\tИсключение',
    '\t\t\tПопытка',
    '\t\t\t\tЗапрРБППрост = Новый Запрос("ВЫБРАТЬ Спр.Код КАК Код, Спр.Наименование КАК Наименование ИЗ Справочник.РасходыБудущихПериодов КАК Спр ГДЕ НЕ Спр.ПометкаУдаления И НЕ Спр.ЭтоГруппа");',
    '\t\t\t\tДля Каждого СтрРБПБ0 Из ЗапрРБППрост.Выполнить().Выгрузить() Цикл',
    '\t\t\t\t\tЗап = Новый Соответствие;',
