    '\t\t\t\t\tЗап.Вставить("Наименование", Строка(СтрРБПБ0.Наименование));',
    '\t\t\t\t\tМассивРБП.Добавить(Зап);',
    '\t\t\t\tКонецЦикла;',
    '\t\t\tИсключение',
