    '\t\tКонецПопытки;',
    '\t\tВсеСправочники.Вставить("РасходыБудущихПериодов", МассивРБП);',
    '',
    '\t\tМассивИЛ = Новый Массив;',
    '\t\tПопытка',
    '\t\t\tЕсли Метаданные.Документы.Найти("ИсполнительныйЛист") <> Неопределено Тогда',
    '\t\t\t\tЗапрИЛ = Новый Запрос("ВЫБРАТЬ ПРЕДСТАВЛЕНИЕ(Док.Сотрудник) КАК Сотрудник, ПРЕДСТАВЛЕНИЕ(Док.Получатель) КАК Получатель, Док.Размер КАК Размер, ПРЕДСТАВЛЕНИЕ(Док.СпособРасчета) КАК СпособРасчета, Док.ДействуетС КАК ДействуетС, Док.ДействуетПо КАК ДействуетПо, Док.Дата КАК Дата ИЗ Документ.ИсполнительныйЛист КАК Док ГДЕ НЕ Док.ПометкаУдаления И Док.Проведен");',
    '\t\t\t\tДля Каждого СтрИЛ Из ЗапрИЛ.Выполнить().Выгрузить() Цикл',
    '\t\t\t\t\tЗапИЛ = Новый Соответствие;',
    '\t\t\t\t\tЗапИЛ.Вставить("Сотрудник", Строка(СтрИЛ.Сотрудник));',
