    '\t\t\t\t\tЗапИЛ.Вставить("СпособРасчета", Строка(СтрИЛ.СпособРасчета));',
    '\t\t\t\t\tЕсли ЗначениеЗаполнено(СтрИЛ.ДействуетС) Тогда',
    '\t\t\t\t\t\tЗапИЛ.Вставить("ДействуетС", Формат(СтрИЛ.ДействуетС, "ДФ=гггг-ММ-дд"));',
    '\t\t\t\t\tКонецЕсли;',
    '\t\t\t\t\tЕсли ЗначениеЗаполнено(СтрИЛ.ДействуетПо) Тогда',
    '\t\t\t\t\t\tЗапИЛ.Вставить("ДействуетПо", Формат(СтрИЛ.ДействуетПо, "ДФ=гггг-ММ-дд"));',
    '\t\t\t\t\tКонецЕсли;',
    '\t\t\t\t\tЗапИЛ.Вставить("Дата", Формат(СтрИЛ.Дата, "ДФ=гггг-ММ-дд"));',
