    '&НаСервере',
    'Функция ПолучитьЖивойОстатокЗарплаты70(ОргСсылка, ДатаДок)',
    '\tСчет70 = НайтиСчет("70");',
    '\tЕсли НЕ ЗначениеЗаполнено(ОргСсылка) Или НЕ ЗначениеЗаполнено(Счет70) Тогда',
    '\t\tВозврат 0;',
    '\tКонецЕсли;',
    '\tПопытка',
    '\t\tЗапрос70 = Новый Запрос;',
    '\t\tЗапрос70.Текст = "ВЫБРАТЬ СУММА(ЕСТЬNULL(Ост.СуммаОстатокКт, 0)) КАК СуммаКт"',
    '\t\t\t+ " ИЗ РегистрБухгалтерии.Хозрасчетный.Остатки(&ДатаГраницы, Счет В ИЕРАРХИИ (&Счет70), , Организация = &Организация) КАК Ост";',
    '\t\tЗапрос70.УстановитьПараметр("ДатаГраницы", НачалоДня(ДатаДок));',
    '\t\tЗапрос70.УстановитьПараметр("Счет70", Счет70);',
    '\t\tЗапрос70.УстановитьПараметр("Организация", ОргСсылка);',
    '\t\tТабл70 = Запрос70.Выполнить().Выгрузить();',
    '\t\tЕсли Табл70.Количество() > 0 Тогда',
    '\t\t\tЖивойДолг70 = Окр(Число(Табл70[0].СуммаКт), 2);',
    '\t\t\tЕсли ЖивойДолг70 > 0 Тогда',
    '\t\t\t\tВозврат ЖивойДолг70;',
    '\t\t\tКонецЕсли;',
    '\t\tКонецЕсли;',
    '\tИсключение',
    '\t\tДобавитьСтрокуЛога("ОШИБКА чтения живого остатка сч. 70 на " + Формат(НачалоДня(ДатаДок), "ДФ=дд.ММ.гггг") + ": " + ОписаниеОшибки());',
    '\tКонецПопытки;',
    '\tВозврат 0;',
    'КонецФункции',
    '',
    '&НаСервере',
    'Функция СоздатьУплатуНалоговПоЖивымОстаткам1С(ОргСсылка, ДокДанные, ИдРихтгофен, КонтрСсылка, ЧерновикСсылка = Неопределено)',
    '\tДатаДок = РазобратьДатуISO(ПолучитьИзСоответствия(ДокДанные, "date", ""), Ложь);',
    '\tДатаГраницы = НачалоДня(ДатаДок);',
