    '\t\tСчетчикСч68 = 0;',
    '\t\tДля Каждого СтрСчБД Из ЗапросВсех68_69.Выполнить().Выгрузить() Цикл',
    '\t\t\tСчетчикСч68 = СчетчикСч68 + 1;',
