    '\t\t\t\tСыройСписокСчетов.Добавить(СтрСчБД.Ссылка);',
    '\t\t\tКонецЕсли;',
    '\t\tКонецЦикла;',
    '\tИсключение',
    '\tКонецПопытки;',
    '',
    '\tСписокСчетов = Новый Массив;',
