    '\t\t		УстановитьЕслиЕсть(ДокОбъект, "СчетРасчетов", НайтиСчет("60.01"));',
    '\t\tУстановитьЕслиЕсть(ДокОбъект, "СчетАвансов", НайтиСчет("60.02"));',
