    '\t\tУстановитьЕслиЕсть(ДокОбъект, "ДоговорКонтрагента", ДогСсылка);',
    '\t\tУстановитьЕслиЕсть(ДокОбъект, "БанковскийСчетОрганизации", ПолучитьБанковскийСчетОрганизации(ОргСсылка));',
    '\t\tУстановитьЕслиЕсть(ДокОбъект, "СуммаВключаетНДС", НДСВключен);',
    '\t\tДля Каждого СтрСч Из СтрокиДок Цикл',
    '\t\t\tНомСсылка = ПолучитьИзСоответствия(КартаНом, Строка(ПолучитьИзСоответствия(СтрСч, "nomenclatureKey", "")), Справочники.Номенклатура.ПустаяСсылка());',
    '\t\t\tТекТов = ДокОбъект.Товары.Добавить();',
