    '\t\tКартаОС = Новый Соответствие;',
    '\t\tКартаРБП = Новый Соответствие;',
    '',
    '\t\t// 3. Пошаговое проведение документов в хронологическом порядке (отсечка ПериодС..ПериодПо СТРОГО до любых запросов к БД)',
    '\t\tСозданоИПроведено = 0;',
