    '\t\tПропущеноВнеПериода = 0;',
    '\t\tРегламентныхШагов = 0;',
    '\t\tСписокАдаптированных6909 = Новый Массив;',
    '',
    '\t\tДатаНачалаЗагрузки = ЭтотОбъект["ПериодС"];',
    '\t\tДатаОкончанияЗагрузки = ЭтотОбъект["ПериодПо"];',
    '\t\tФильтрСЗадан = ЗначениеЗаполнено(ДатаНачалаЗагрузки);',
