    '\t\t\t\t+ " по "',
    '\t\t\t\t+ ?(ФильтрПоЗадан, Формат(ДатаОкончанияЗагрузки, "ДФ=дд.ММ.гггг"), "конец пакета"));',
    '\t\tКонецЕсли;',
    '',
    '\t\tМассивДокументов = ПолучитьИзСоответствия(Пакет, "documents", Новый Массив);',
