    '\t\tДля Каждого ДокЭл Из МассивДокументов Цикл',
    '\t\t\tСчетчикДокументовЦикла = СчетчикДокументовЦикла + 1;',
    '\t\t\tЕсли СчетчикДокументовЦикла > 5000 Тогда',
    '\t\t\t\tДобавитьСтрокуЛога("ПРЕДУПРЕЖДЕНИЕ: Сработал предохранитель цикла документов (> 5000 итераций).");',
    '\t\t\t\tПрервать;',
    '\t\t\tКонецЕсли;',
    '\t\t\tИдРихтгофен = СокрЛП(Строка(ПолучитьИзСоответствия(ДокЭл, "richthofenId", "")));',
    '\t\t\tДатаСтр = Строка(ПолучитьИзСоответствия(ДокЭл, "date", ""));',
    '\t\t\tДатаДокПроверка = РазобратьДатуISO(ДатаСтр, Ложь);',
    '\t\t\tЕсли ФильтрСЗадан И ДатаДокПроверка < ДатаНачалаЗагрузки Тогда',
    '\t\t\t\tПропущеноВнеПериода = ПропущеноВнеПериода + 1;',
    '\t\t\t\tПродолжить;',
    '\t\t\tКонецЕсли;',
    '\t\t\tЕсли ФильтрПоЗадан И ДатаДокПроверка > ДатаОкончанияЗагрузки Тогда',
    '\t\t\t\tПропущеноВнеПериода = ПропущеноВнеПериода + 1;',
    '\t\t\t\tПродолжить;',
    '\t\t\tКонецЕсли;',
    '',
    '\t\t\tВидМета = Строка(ПолучитьИзСоответствия(ДокЭл, "metaType1C", "ОперацияБух"));',
    '\t\t\tВидМетаРеальный = РазрешитьИмяДокументаБП30(ВидМета);',
    '\t\t\tСтратегия = Строка(ПолучитьИзСоответствия(ДокЭл, "executionStrategy", "native"));',
    '\t\t\tКомментарийЧист = Строка(ПолучитьИзСоответствия(ДокЭл, "comment", ""));',
    '\t\t\tЕсли НЕ ПустаяСтрока(ИдРихтгофен) Тогда',
