    '\t\t\t\tРегламентныхШагов = РегламентныхШагов + 1;',
    '\t\t\t\tДобавитьСтрокуЛога("[РЕГЛАМЕНТ " + ДатаСтр + "] Выполните штатно в 1С: Операции -> Закрытие месяца (" + Лев(КомментарийЧист, 90) + ")");',
    '\t\t\t\tПродолжить;',
    '\t\t\tКонецЕсли;',
    '',
    '\t\t\tЕсли ВидМета = "ЗакрытиеМесяца" И ЭтотОбъект["ПропускатьЗакрытиеМесяца"] Тогда',
    '\t\t\t\tРегламентныхШагов = РегламентныхШагов + 1;',
    '\t\t\t\tДобавитьСтрокуЛога("[РЕГЛАМЕНТ " + ДатаСтр + "] Пропущено Закрытие месяца — запустите помощник в 1С.");',
    '\t\t\t\tПродолжить;',
    '\t\t\tКонецЕсли;',
    '',
