    '\t\t\t\tДобавитьСтрокуЛога("[РЕГЛАМЕНТ " + ДатаСтр + "] Пропущено Начисление зарплаты — выполните штатно в 1С.");',
    '\t\t\t\tПродолжить;',
    '\t\t\tКонецЕсли;',
    '',
    '\t\t\tШапкаД = ПолучитьИзСоответствия(ДокЭл, "header", Новый Соответствие);',
    '\t\t\tРежимДинОстатка = Строка(ПолучитьИзСоответствия(ДокЭл, "dynamicBalanceMode", ПолучитьИзСоответствия(ШапкаД, "dynamicBalanceMode", "")));',
    '',
    '\t\t\t// Умная проверка дублей по тегу [RichthofenID:<id>] (строго после отсечки по периоду):',
