    '\t\t\tЕсли ИнфоДубля.НайденПроведенный И НЕ (РежимДинОстатка = "taxes_all" И ВидМетаРеальный = "СписаниеСРасчетногоСчета") Тогда',
    '\t\t\t\tПропущеноДублей = ПропущеноДублей + 1;',
    '\t\t\t\tПродолжить;',
    '\t\t\tКонецЕсли;',
    '\t\t\tЧерновикДляПерезаписи = ИнфоДубля.СсылкаЧерновика;',
    '',
    '\t\t\t// Синхронизируем справочники ТОЛЬКО для документов выбранного периода',
    '\t\t\tПодготовитьСправочникиДляДокументаПакета(ДокЭл, ОргСсылка, ВалютаРубПакет, СырыеКонтрПакета, СырыеДогПакета, СырыеНомПакета, СырыеСотрПакета, СырыеОСПакета, СырыеРБППакета, КартаКонтр, КартаДог, КартаНом, КартаСотр, КартаОС, КартаРБП, КэшКонтрПоИНН, КэшКонтрПоНормИмени, КэшДоговоров);',
    '',
    '\t\t\tКонтрД = ПолучитьИзСоответствия(КартаКонтр, Строка(ПолучитьИзСоответствия(ШапкаД, "counterpartyKey", "")), Справочники.Контрагенты.ПустаяСсылка());',
    '\t\t\tДогД = ПолучитьИзСоответствия(КартаДог, Строка(ПолучитьИзСоответствия(ШапкаД, "contractKey", "")), Справочники.ДоговорыКонтрагентов.ПустаяСсылка());',
    '\t\t\tСотрД = ПолучитьИзСоответствия(КартаСотр, Строка(ПолучитьИзСоответствия(ШапкаД, "employeeKey", "")), Неопределено);',
    '\t\t\tСкладД = НайтиИлиСоздатьСклад(Строка(ПолучитьИзСоответствия(ШапкаД, "warehouseName", "Основной склад")));',
    '',
    '\t\t\t// Точечная проверка ручного дубля Базы 0 одним запросом ПЕРВЫЕ 1 по конкретному виду документа',
