    '\t\t\t\tСуммаДляСверкиРуч = Число(ПолучитьИзСоответствия(ШапкаД, "amount", 0));',
    '\t\t\t\tЕсли РежимДинОстатка = "payroll_balance" Тогда',
    '\t\t\t\t\tЖивойДолгЗПРуч = ПолучитьЖивойОстатокЗарплаты70(ОргСсылка, ДатаДокПроверка);',
    '\t\t\t\t\tЕсли ЖивойДолгЗПРуч > 0 Тогда',
    '\t\t\t\t\t\tСуммаДляСверкиРуч = ЖивойДолгЗПРуч;',
    '\t\t\t\t\tКонецЕсли;',
    '\t\t\t\tКонецЕсли;',
    '\t\t\t\tНайденныйРучнойДок = НайтиСуществующийРучнойДубльДокумента(ВидМетаРеальный, ОргСсылка, ДатаДокПроверка, КонтрД, СуммаДляСверкиРуч, СотрД);',
    '\t\t\t\tЕсли ЗначениеЗаполнено(НайденныйРучнойДок) Тогда',
    '\t\t\t\t\tПропущеноДублей = ПропущеноДублей + 1;',
    '\t\t\t\t\tДобавитьСтрокуЛога("[ПРОПУСК РУЧНОГО ДУБЛЯ " + ДатаСтр + "] В базе уже проведен документ: " + Строка(НайденныйРучнойДок));',
    '\t\t\t\t\tПродолжить;',
    '\t\t\t\tКонецЕсли;',
    '\t\t\tКонецЕсли;',
    '',
    '\t\t\tОчиститьСообщенияПользователю();',
    '\t\t\tПопытка',
    '\t\t\t\tЕсли Стратегия = "manual_operation" Или ВидМета = "ОперацияБух" Тогда',
    '\t\t\t\t\tСозданнаяСсылка = ЗаписатьОперациюБухИзПроводок(ОргСсылка, ДокЭл, ТегКомментария, КонтрД, ДогД, СкладД, СотрД, КартаНом, КартаОС, КартаРБП, СписокАдаптированных6909, ЧерновикДляПерезаписи);',
    '\t\t\t\t\tСозданоИПроведено = СозданоИПроведено + 1;',
    '\t\t\t\t\tЕсли ЗначениеЗаполнено(ЧерновикДляПерезаписи) Тогда',
    '\t\t\t\t\t\tПерезаписаноЧерновиков = ПерезаписаноЧерновиков + 1;',
    '\t\t\t\t\tКонецЕсли;',
    '\t\t\t\tИначеЕсли РежимДинОстатка = "taxes_all" И ВидМетаРеальный = "СписаниеСРасчетногоСчета" Тогда',
    '\t\t\t\t\tКолПлатежекНал = СоздатьУплатуНалоговПоЖивымОстаткам1С(ОргСсылка, ДокЭл, ИдРихтгофен, КонтрД, ЧерновикДляПерезаписи);',
    '\t\t\t\t\tЕсли КолПлатежекНал = 0 Тогда',
    '\t\t\t\t\t\tПропущеноДублей = ПропущеноДублей + 1;',
    '\t\t\t\t\tИначе',
    '\t\t\t\t\t\tСозданоИПроведено = СозданоИПроведено + КолПлатежекНал;',
    '\t\t\t\t\t\tЕсли ЗначениеЗаполнено(ЧерновикДляПерезаписи) Тогда',
    '\t\t\t\t\t\t\tПерезаписаноЧерновиков = ПерезаписаноЧерновиков + 1;',
    '\t\t\t\t\t\tКонецЕсли;',
    '\t\t\t\t\tКонецЕсли;',
    '\t\t\t\tИначе',
    '\t\t\t\t\tСозданнаяСсылка = СоздатьНативныйДокумент1С(ОргСсылка, ДокЭл, ТегКомментария, КартаКонтр, КартаДог, КартаНом, КартаСотр, КартаОС, КартаРБП, ЧерновикДляПерезаписи, ИдРихтгофен, КэшКонтрПоНормИмени, КэшДоговоров, ВалютаРубПакет);',
    '\t\t\t\t\tЕсли СозданнаяСсылка = Неопределено Тогда',
    '\t\t\t\t\t\tЧерновиковСОшибками = ЧерновиковСОшибками + 1;',
    '\t\t\t\t\tИначе',
    '\t\t\t\t\t\tСозданоИПроведено = СозданоИПроведено + 1;',
    '\t\t\t\t\t\tЕсли ЗначениеЗаполнено(ЧерновикДляПерезаписи) Тогда',
    '\t\t\t\t\t\t\tПерезаписаноЧерновиков = ПерезаписаноЧерновиков + 1;',
    '\t\t\t\t\t\t\tДобавитьСтрокуЛога("[ПЕРЕПРОВЕДЕН ЧЕРНОВИК] " + ВидМетаРеальный + " от " + ДатаСтр + " (" + ИдРихтгофен + ")");',
    '\t\t\t\t\t\tКонецЕсли;',
    '\t\t\t\t\tКонецЕсли;',
    '\t\t\t\tКонецЕсли;',
